//! File and folder icons for the explorer, using artwork from the
//! [vscode-icons](https://github.com/vscode-icons/vscode-icons) project
//! (CC BY-SA 4.0, see `assets/vscode-icons/LICENSE.md`).
//!
//! Every SVG in `assets/vscode-icons` is embedded at build time (see
//! `build.rs`); this module maps file and folder names onto them.

use std::collections::HashMap;
use std::sync::OnceLock;

use egui::{Image, ImageSource, Ui, Vec2, load::Bytes};

/// `(icon name, image uri, svg bytes)`, generated by `build.rs`.
static EMBEDDED: &[(&str, &str, &[u8])] = include!(concat!(env!("OUT_DIR"), "/vscode_icons.rs"));

/// Rendered icon size in points.
pub const SIZE: f32 = 16.0;

