struct Lookup {
    icons: HashMap<&'static str, (&'static str, &'static [u8])>,
    names: HashMap<&'static str, &'static str>,
    extensions: HashMap<&'static str, &'static str>,
    folders: HashMap<&'static str, &'static str>,
}

fn lookup() -> &'static Lookup {
    static LOOKUP: OnceLock<Lookup> = OnceLock::new();
    LOOKUP.get_or_init(|| Lookup {
        icons: EMBEDDED
            .iter()
            .map(|&(name, uri, bytes)| (name, (uri, bytes)))
            .collect(),
        names: FILE_NAMES.iter().copied().collect(),
        extensions: FILE_EXTENSIONS.iter().copied().collect(),
        folders: FOLDERS.iter().copied().collect(),
    })
}

/// The `file_type_*` icon key for a file name, if a specific one applies.
fn file_type(name: &str) -> Option<&'static str> {
    let l = lookup();
    let lower = name.to_ascii_lowercase();
    if let Some(&t) = l.names.get(lower.as_str()) {
        return Some(t);
    }
    if let Some(&(_, t)) = FILE_PREFIXES.iter().find(|(p, _)| lower.starts_with(p)) {
        return Some(t);
    }
    // Try each suffix after a dot, longest first. A leading dot marks a
    // hidden file, not an extension.
    lower
        .char_indices()
        .skip(1)
        .filter(|&(_, c)| c == '.')
        .find_map(|(i, _)| l.extensions.get(&lower[i + 1..]).copied())
}

/// Resolves `{prefix}{key}{suffix}`, preferring a `light_` variant on light
/// themes, and returns its embedded image.
fn resolve(prefix: &str, key: &str, suffix: &str, dark: bool) -> Option<ImageSource<'static>> {
    let icons = &lookup().icons;
    let light = (!dark)
        .then(|| icons.get(format!("{prefix}light_{key}{suffix}").as_str()))
        .flatten();
    let &(uri, bytes) = light.or_else(|| icons.get(format!("{prefix}{key}{suffix}").as_str()))?;
    Some(ImageSource::Bytes {
        uri: uri.into(),
        bytes: Bytes::Static(bytes),
    })
}

/// The icon for a file called `name`.
pub fn file(name: &str, dark: bool) -> ImageSource<'static> {
    file_type(name)
        .and_then(|t| resolve("file_type_", t, "", dark))
        .or_else(|| resolve("", "default_file", "", dark))
        .expect("default_file icon is embedded")
}

/// The icon for a folder called `name`, drawn open or closed.
pub fn folder(name: &str, open: bool, is_root: bool, dark: bool) -> ImageSource<'static> {
    let suffix = if open { "_opened" } else { "" };
    let specific = (!is_root)
        .then(|| {
            lookup()
                .folders
                .get(name.to_ascii_lowercase().as_str())
                .copied()
        })
        .flatten()
        .and_then(|t| resolve("folder_type_", t, suffix, dark));
    let default = if is_root {
        "default_root_folder"
    } else {
        "default_folder"
    };
    specific
        .or_else(|| resolve("", default, suffix, dark))
        .expect("default folder icons are embedded")
}

/// Shows `source` at the standard icon size.
pub fn show(ui: &mut Ui, source: ImageSource<'static>) -> egui::Response {
    ui.add(Image::new(source).fit_to_exact_size(Vec2::splat(SIZE)))
}

#[cfg(test)]
mod tests {
    use super::*;

    fn uri(source: ImageSource<'static>) -> String {
        match source {
            ImageSource::Bytes { uri, .. } => uri.into_owned(),
            _ => unreachable!(),
        }
    }

    #[test]
    fn every_mapping_has_an_embedded_icon() {
        let icons = &lookup().icons;
        let files = FILE_NAMES
            .iter()
            .chain(FILE_PREFIXES)
            .chain(FILE_EXTENSIONS);
        for &(pattern, key) in files {
            let name = format!("file_type_{key}");
            assert!(
                icons.contains_key(name.as_str()),
                "{pattern}: missing {name}"
            );
        }
        for &(pattern, key) in FOLDERS {
            for suffix in ["", "_opened"] {
                let name = format!("folder_type_{key}{suffix}");
                assert!(
                    icons.contains_key(name.as_str()),
                    "{pattern}: missing {name}"
                );
            }
        }
    }

    #[test]
    fn resolves_files() {
        assert!(uri(file("main.rs", true)).ends_with("/file_type_rust.svg"));
        assert!(uri(file("Cargo.toml", true)).ends_with("/file_type_cargo.svg"));
        assert!(uri(file("types.d.ts", true)).ends_with("/file_type_typescriptdef.svg"));
        assert!(uri(file("app.test.ts", true)).ends_with("/file_type_testts.svg"));
        assert!(uri(file("vite.config.ts", true)).ends_with("/file_type_vite.svg"));
        assert!(uri(file(".env.local", true)).ends_with("/file_type_dotenv.svg"));
        assert!(uri(file(".bashrc", true)).ends_with("/default_file.svg"));
        assert!(uri(file("mystery", true)).ends_with("/default_file.svg"));
        assert!(uri(file("Cargo.toml", false)).ends_with("/file_type_cargo.svg"));
        assert!(uri(file("x.toml", false)).ends_with("/file_type_light_toml.svg"));
    }

    #[test]
    fn resolves_folders() {
        assert!(uri(folder("src", false, false, true)).ends_with("/folder_type_src.svg"));
        assert!(uri(folder("src", true, false, true)).ends_with("/folder_type_src_opened.svg"));
        assert!(uri(folder("misc", true, false, true)).ends_with("/default_folder_opened.svg"));
        assert!(uri(folder("src", true, true, true)).ends_with("/default_root_folder_opened.svg"));
    }
}
